type Account struct {
	mu      sync.Mutex   // never copied: address it as *Account only
	balance int64
}

func (a *Account) Lock()   { a.mu.Lock() }   // published lock (sync.Locker)
func (a *Account) Unlock() { a.mu.Unlock() }

func Transfer(from, to *Account, amount int64) {
	from.Lock()
	to.Lock()               // fixed global order: from before to
	from.balance -= amount
	to.balance += amount
	to.Unlock()
	from.Unlock()
}
